## 4️⃣ Front‑end – HTML + JavaScript

Create a folder called **`public`** (or whatever you configured) and put `index.html` inside:

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>Users on Google Maps</title>
  <style>
    /* Full‑screen map */
    #map { height: 100vh; width: 100%; }
    /* Optional: a small loading spinner */
    #loading { position:absolute; top:10px; left:10px; background:#fff; padding:5px 10px; border-radius:4px; }
  </style>
</head>
<body>

<div id="loading">Loading map…</div>
<div id="map"></div>

<!-- 1️⃣ Load the Maps JavaScript API (replace YOUR_API_KEY) -->
<script src="https://maps.googleapis.com/maps/api/js?key=YOUR_API_KEY&callback=initMap"
        async defer></script>

<script>
/* ------------------------------------------------------------------
   2️⃣ initMap – called automatically by the Maps API (callback param)
   ------------------------------------------------------------------ */
function initMap() {
  // Hide the loading message as soon as the API is ready
  document.getElementById('loading').style.display = 'none';

  // Default center (will be overwritten by geolocation)
  const defaultCenter = { lat: 39.8283, lng: -98.5795 }; // geographic center of US

  // Create the map object
  const map = new google.maps.Map(document.getElementById('map'), {
    zoom: 4,
    center: defaultCenter
  });

  // ----------------------------------------------------------------
  // 3️⃣ Get the current user’s location (HTML5 Geolocation)
  // ----------------------------------------------------------------
  if (navigator.geolocation) {
    navigator.geolocation.getCurrentPosition(
      position => {
        const userPos = {
          lat: position.coords.latitude,
          lng: position.coords.longitude
        };
        // Re‑center map on the user
        map.setCenter(userPos);
        map.setZoom(12);

        // Marker for the current user
        new google.maps.Marker({
          position: userPos,
          map,
          title: 'You are here',
          icon: {
            path: google.maps.SymbolPath.CIRCLE,
            scale: 8,
            fillColor: '#4285F4',
            fillOpacity: 1,
            strokeWeight: 2,
            strokeColor: '#fff'
          }
        });
      },
      err => {
        console.warn('Geolocation failed: ', err);
        // Keep default center if user denies permission
      }
    );
  } else {
    console.warn('Browser does not support geolocation');
  }

  // ----------------------------------------------------------------
  // 4️⃣ Load other users from the server and add markers
  // ----------------------------------------------------------------
  fetch('/api/users')
    .then(resp => resp.json())
    .then(users => {
      users.forEach(u => {
        const marker = new google.maps.Marker({
          position: { lat: u.lat, lng: u.lng },
          map,
          title: u.name
        });

        // Optional: info window on click
        const info = new google.maps.InfoWindow({
          content: `<strong>${u.name}</strong>`
        });
        marker.addListener('click', () => info.open(map, marker));
      });
    })
    .catch(err => console.error('Failed to load users:', err));
}
</script>
</body>
</html>
```

### What this does

| Step | Code | Result |
|------|------|--------|
| **Load Maps API** | `<script src="https://maps.googleapis.com/maps/api/js?key=YOUR_API_KEY&callback=initMap" async defer></script>` | Google injects the `google.maps` namespace and calls `initMap` when ready. |
| **Create map** | `new google.maps.Map(...)` | Blank map centered on the US (or any default). |
| **Geolocation** | `navigator.geolocation.getCurrentPosition(...)` | If the user allows, the map recenters on their exact lat/lng and a blue dot marker appears. |
| **Fetch users** | `fetch('/api/users')` | Calls the server endpoint we built earlier. |
| **Add markers** | `new google.maps.Marker({position:{lat:u.lat,lng:u.lng}, map, title:u.name})` | One marker per user from the DB. |
| **Info windows** | `new google.maps.InfoWindow(...)` + click listener | Clicking a marker shows the user’s name (customize as you like). |

