### 6.1  OpenAI Assistant – create & run

```ts
// src/services/openaiAssistants.ts
import axios from 'axios';

const OPENAI_BASE = 'https://api.openai.com/v1';

export async function createAssistant() {
  const resp = await axios.post(
    `${OPENAI_BASE}/assistants`,
    {
      model: 'gpt-4o',
      name: 'Travel Planner',
      instructions:
        'You are a travel‑planning assistant. Return a JSON itinerary with fields: day, activity, location, start_time, end_time, notes.',
      tools: [
        { type: 'function', function: { name: 'search_weather', description: 'Get forecast for a location/date', parameters: {/* … */} } },
        { type: 'function', function: { name: 'convert_currency', description: 'Convert amount to user base currency', parameters: {/* … */} } },
      ],
    },
    {
      headers: { Authorization: `Bearer ${process.env.OPENAI_API_KEY}` },
    }
  );
  return resp.data.id; // assistant_id
}

export async function runAssistant(assistantId: string, userPrompt: string) {
  // 1️⃣ create a thread
  const thread = await axios.post(
    `${OPENAI_BASE}/assistants/${assistantId}/threads`,
    {},
    { headers: { Authorization: `Bearer ${process.env.OPENAI_API_KEY}` } }
  );

  // 2️⃣ add a message + start a run
  const run = await axios.post(
    `${OPENAI_BASE}/threads/${thread.data.id}/runs`,
    {
      assistant_id: assistantId,
      instructions: userPrompt,
    },
    { headers: { Authorization: `Bearer ${process.env.OPENAI_API_KEY}` } }
  );

  // 3️⃣ poll until `status === 'completed'`
  let completed = false;
  let result: any;
  while (!completed) {
    const status = await axios.get(
      `${OPENAI_BASE}/threads/${thread.data.id}/runs/${run.data.id}`,
      { headers: { Authorization: `Bearer ${process.env.OPENAI_API_KEY}` } }
    );
    completed = status.data.status === 'completed';
    if (completed) result = status.data;
    else await new Promise(r => setTimeout(r, 500));
  }

  // `result.output` contains the JSON itinerary (or tool calls)
  return result.output;
}
```

### 6.2  Weather – One Call (cached)

```ts
// src/services/weather.ts
import axios from 'axios';
import NodeCache from 'node-cache';
const cache = new NodeCache({ stdTTL: 3600 }); // 1 h

export async function getDailyForecast(lat: number, lon: number) {
  const cacheKey = `weather:${lat}:${lon}`;
  const cached = cache.get(cacheKey);
  if (cached) return cached as any;

  const resp = await axios.get(
    `https://api.openweathermap.org/data/2.5/onecall`,
    {
      params: {
        lat,
        lon,
        exclude: 'minutely,alerts',
        units: 'metric',
        appid: process.env.OPENWEATHERMAP_API_KEY,
      },
    }
  );

  cache.set(cacheKey, resp.data);
  return resp.data;
}
```

