  let rate: number;

  if (cached) {
    rate = cached as number;
  } else {
    const endpoint = date ? 'historical' : 'live';
    const resp = await axios.get(
      `http://api.currencylayer.com/${endpoint}`,
      {
        params: {
          access_key: process.env.CURRENCYLAYER_API_KEY,
          currencies: from,
          source: base,
          ...(date && { date }), // historical endpoint needs `date=YYYY-MM-DD`
        },
      }
    );

    if (!resp.data.success) throw new Error(resp.data.error.info);
    rate = resp.data.quotes[`USD${from}`]; // live rates are USD‑based
    cache.set(cacheKey, rate);
  }

  return {
    converted: amount * rate,
    rate,
    conversionDate: date ?? new Date().toISOString().split('T')[0],
  };
}
```

### 6.4  Real‑time push (Pusher)

```ts
// src/services/pusher.ts
import Pusher from 'pusher';

export const pusher = new Pusher({
  appId: process.env.PUSHER_APP_ID!,
  key: process.env.PUSHER_KEY!,
  secret: process.env.PUSHER_SECRET!,
  cluster: process.env.PUSHER_CLUSTER!,
  useTLS: true,
});

export function pushEvent(tripId: string, event: string, payload: any) {
  pusher.trigger(`trip-${tripId}`, event, payload);
}
```

### 6.5  Expense endpoint (with moderation, whisper & conversion)

```ts
// src/routes/expenses.ts
router.post(
  '/api/trips/:tripId/expenses',
  async (req, res) => {
    const { amount, currency, date, notes } = req.body;
    const file = req.files?.receipt; // multer / busboy
    const voice = req.files?.voice;   // optional

    // 1️⃣ moderation
    const mod = await axios.post(
      'https://api.openai.com/v1/moderations',
      { input: notes },
      { headers: { Authorization: `Bearer ${process.env.OPENAI_API_KEY}` } }
    );
    if (mod.data.results[0].flagged) {
      return res.status(400).json({ error: 'Inappropriate content' });
    }

    // 2️⃣ optional transcription
    let transcript = null;
    if (voice) {
      const voiceUrl = await uploadToS3(voice);
      const whisper = await axios.post(
        'https://api.openai.com/v1/audio/transcriptions',
        {
          file: fs.createReadStream(voice.path),
          model: 'whisper-1',
        },
        {
          headers: {
            Authorization: `Bearer ${process.env.OPENAI_API_KEY}`,
            'Content-Type': 'multipart/form-data',
          },
        }
      );
      transcript = whisper.data.text;
    }

    // 3️⃣ currency conversion
    const { converted, rate, conversionDate } = await convertToBase(
      amount,
      currency,
      req.user.baseCurrency,
      date
    );

    // 4️⃣ store receipt (if any)
    let receiptUrl = null;
    if (file) receiptUrl = await uploadToS3(file);

    // 5️⃣ persist
    const expense = await db('expenses').insert({
      trip_id: req.params.tripId,
      user_id: req.user.id,
      original_amount: amount,
      original_currency: currency,
      date,
      notes,
      transcript,
      receipt_url: receiptUrl,
      converted_amount: converted,
      conversion_rate: rate,
      conversion_date: conversionDate,
    }).returning('*');

    // 6️⃣ push real‑time update
    pushEvent(req.params.tripId, 'expense_added', expense[0]);

    res.json(expense[0]);
  }
);
```

